    units_per_order_by_country = (
        sale_df.groupby(['Shipping Country', 'Name'])['Lineitem quantity']
        .sum()
        .reset_index()
        .groupby('Shipping Country')
        .agg(total_units=('Lineitem quantity', 'sum'), total_orders=('Name', 'nunique'))
        .reset_index()
    )
    units_per_order_by_country['avg_units_per_order'] = (
        units_per_order_by_country['total_units'] / units_per_order_by_country['total_orders']
    )

    top10 = units_per_order_by_country.nlargest(10, 'total_orders')

    seg_results = [
        {"name": str(row['Shipping Country']), "value": round(float(row['avg_units_per_order']), 4)}
        for _, row in top10.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Lineitem quantity",
        "aggregation": "ratio",
        "label": "avg_units_per_order",
        "results": seg_results
    })

    overall_orders = sale_df.groupby('Name')['Lineitem quantity'].sum()
    overall_avg = float(overall_orders.mean())
    overall_count = int(overall_orders.nunique())

    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Lineitem quantity",
        "aggregation": "ratio",
        "label": "avg_units_per_order_overall",
        "results": [{"name": "ALL", "value": round(overall_avg, 4)}]
    })

    result['assumptions'].append(
        f"avg_units_per_order = sum(Lineitem quantity) / count(distinct order_id) per country, sale+USD rows only; overall avg across {overall_count} orders = {overall_avg:.4f}"
    )
    result['assumptions'].append(
        "Top 10 countries by order count shown; all other countries excluded from segment table."
    )
except Exception as e:
    result['anomalies'].append({
        "column": "Lineitem quantity",
        "row_index": None,
        "value": str(e),
        "expected_range": "N/A",
        "severity": "low",
        "explanation": "Segmentation step failed."
    })

