try:
    if (_date or _hints) and False:
        # A mid-month export compares the last two complete months (agents.utils.partial_last_month).
        def _cut(_t):
            _mm = _t.dt.to_period('M')
            _d = _t.dropna()
            if _d.empty:
                return _mm
            _days = _d.dt.normalize().groupby(_d.dt.to_period('M')).nunique().sort_index()
            _g = _d.dt.normalize().drop_duplicates().sort_values().diff().dt.days.dropna()
            _regular = len(_g) >= 3 and _g.std() <= 0.25 * _g.mean()
            if len(_days) >= 3 and _d.max().normalize() < _d.max().normalize() + pd.offsets.MonthEnd(0) and (_days.iloc[:-1].median() >= 4 or _regular) and _days.iloc[-1] < 0.9 * _days.iloc[:-1].median():
